(()=>{"use strict";const e=document.getElementById("calculator-form"),t=document.getElementById("result"),n=t.querySelector(".result-value"),r=new Intl.NumberFormat(void 0,{style:"currency",currency:"USD"});e.addEventListener("submit",e=>{e.preventDefault();const u=function(){const e=[document.getElementById("principal").value,document.getElementById("rate").value,document.getElementById("years").value];if(e.some(e=>null==e||""===String(e).trim()))return null;const[t,n,r]=e.map(Number);if(!Number.isFinite(t)||!Number.isFinite(n)||!Number.isFinite(r)||t<0||n<0||r<0)return null;const u=t*Math.pow(1+n/100,r);return Number.isFinite(u)?Math.round(100*u)/100:null}();t.classList.toggle("is-error",null===u),n.textContent=null===u?"Enter a valid, non-negative value in every field.":r.format(u)})})();